"""Render the same regional analysis to a self-contained HTML and a reviewed PDF.
Uses the bundled Python runtime (pandas, Pillow and ReportLab).
"""
from pathlib import Path
import json, base64, html, re, shutil, zipfile
import pandas as pd
from PIL import Image
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont
from reportlab.lib.styles import ParagraphStyle
from reportlab.platypus import Paragraph, Table, TableStyle

ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'outputs/regional_resilience_20260920';T=OUT/'tables'
PREV=ROOT/'outputs/clean_research_full_20260920';PDFDIR=ROOT/'output/pdf';PDFDIR.mkdir(parents=True,exist_ok=True)
r=pd.read_csv(T/'regional_results.csv').set_index('region');q=json.loads((OUT/'summary.json').read_text())
f=pd.read_csv(T/'fine_robustness.csv').set_index('model');rr=pd.read_csv(PREV/'tables/regional_models.csv').set_index('region')
loo=pd.read_csv(PREV/'tables/leave_one_region_out.csv');dloo=pd.read_csv(T/'dose_leave_one_region_out.csv')
cor=pd.read_csv(T/'context_correlations.csv').set_index('column');sens=pd.read_csv(T/'index_sensitivity.csv')
manifest=json.loads((OUT/'chart_manifest.json').read_text())
def n(x,d=1):return f'{x:,.{d}f}'.replace(',',' ').replace('.',',')
def fmtmodel(label):
 a=f.loc[label];return f'{n(a.beta,2)} п.п. (95% ДИ {n(a.ci_low,2)}…{n(a.ci_high,2)}; p={n(a.p_value,4)})'

