def para(txt,x,y,width,sty='body'):
 # Escape text but retain intended bold/link markup when explicitly supplied.
 p=Paragraph(txt,styles[sty]);_,height=p.wrap(width,10000);p.drawOn(cv,x,y-height);return y-height-9
def begin(title=None,eyebrow='РЕГИОНАЛЬНАЯ УСТОЙЧИВОСТЬ · 2026'):
 global page
 page+=1;cv.setFillColor(colors.white);cv.rect(0,0,W,H,fill=1,stroke=0);cv.setFillColor(colors.HexColor('#526b82'));cv.setFont('DejaVu',8);cv.drawString(M,H-24,eyebrow)
 y=H-47
 if title:y=para(title,M,y,PW,'h1')-8
 return y
def end(min_y,title):
 assert min_y>38,(page,title,min_y)
 cv.setStrokeColor(colors.HexColor('#d5dfe8'));cv.line(M,30,W-M,30);cv.setFillColor(colors.HexColor('#5d7285'));cv.setFont('DejaVu',7.5);cv.drawString(M,17,'Данные: апрель–август 2026. Контекст и сообщения проверены 20.09.2026.');cv.drawRightString(W-M,17,str(page));cv.showPage();page_meta.append(dict(page=page,title=title,lowest_content_y=min_y))
def text_page(title,ps):
 y=begin(title)
 for p in ps:y=para(p,M,y,PW)
 end(y,title)

